 A.DSV_FLG,
 /* PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/
  A.DV_ROUTE_TO_MARKET_CD,
 /*PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/
A.DV_AS_OF_FSC_MTH_RTM_CD,
A.DV_DEAL_ID  /*as part SOT June CDR*/,
